def process(event, state, timers):
    sv = state.source_versions.get(event.source, -1)
    if event.source_version <= sv:
        return                                   # stale or duplicate
    state.source_versions[event.source] = event.source_version
    state.apply(event.fields, event.op)
    state.doc_version += 1                       # monotonic per product
    state.dirty |= classify(event.fields)        # {AVAIL, CONTENT}
    if not state.timer_set:
        window = 200 if state.dirty == {AVAIL} else 500   # ms
        timers.register(now() + window); state.timer_set = True

def on_timer(state):
    if CONTENT in state.dirty:
        emit('idx.content', state.full_doc(), version=state.doc_version)
    if AVAIL in state.dirty:
        emit('idx.avail', state.avail_doc(), version=state.doc_version)
    state.dirty, state.timer_set = set(), False

def run(consumer, es):
    limit = AIMD(min=2, max=64, start=8)
    while True:
        batch = consumer.poll(max_bytes=10_MB, max_wait_ms=50)
        limit.acquire()
        resp = es.bulk(to_actions(batch), timeout='30s')
        retry = []
        for item in resp.items:
            if item.status in (200, 201, 409): continue
            elif item.status == 429: retry.append(item)
            elif attempts(item) >= 5: dlq.send(item)
            else: retry.append(item)
        if any(i.status == 429 for i in resp.items): limit.on_reject()
        else: limit.on_success()
        sleep(backoff_with_jitter(attempt)) if retry else None
        resend(retry)                 # loop until empty or DLQ
        consumer.commit(batch.last_offsets)
